<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useSessionStore} from '@/stores/session'
import {useServiceContext} from '@/composables/useServiceContext'
import {ApiError,asApiError,requestBytes} from '@/api/client'
import {serviceRequest,query} from '@/api/modules/clientServices'
import {validSupplyId,type SupplyAsset} from '@/api/modules/supply'
import {invoiceStatuses,invoiceActions,invoiceBase,invoiceRoute,invoiceAvailableActions,invoiceAmount,invoiceMoney,isInvoice,isInvoiceHeader,isInvoiceEligibility,isInvoiceEvent,isInvoiceDocument,invoicePage,type Invoice,type InvoiceRole,type InvoiceHeader,type InvoiceEvent,type InvoiceDocument,type InvoiceEligibility,type InvoiceAction} from '@/api/modules/invoices'
import ServiceWorkspace from '@/components/ServiceWorkspace.vue'
import PrivateAssetPicker from '@/components/PrivateAssetPicker.vue'
import InvoiceHeaderFields from '@/components/InvoiceHeaderFields.vue'
import ApiErrorAlert from '@/components/ApiErrorAlert.vue'
const session=useSessionStore(),route=useRoute(),router=useRouter()
const role=computed<InvoiceRole>(()=>route.meta.invoiceRole==='handle'?'handle':route.meta.invoiceRole==='verify'?'verify':'applicant'),operator=computed(()=>role.value!=='applicant'),creating=computed(()=>route.name==='invoice-new'),id=computed(()=>String(route.params.invoiceId||'')),orderId=computed(()=>String(route.params.orderId||''))
const text=ref(''),header=ref<InvoiceHeader>({kind:'PERSON',title:'',tax_id:null}),amount=ref(''),assets=ref<SupplyAsset[]>([]),uploadLocked=ref(false),action=ref<InvoiceAction|''>(''),reference=ref(''),issuedAt=ref(''),confirmed=ref(false),conflicted=ref(false),reconfirmed=ref(false),baseline=ref('')
const dirty=computed(()=>!!(text.value||amount.value||assets.value.length||reference.value||issuedAt.value||JSON.stringify(header.value)!==baseline.value))
const ui=useServiceContext(()=>operator.value?null:session.selectedId||null,()=>dirty.value,()=>uploadLocked.value),{error,notice,busy,pending}=ui
const locked=computed(()=>busy.value||!!pending.value||uploadLocked.value),canOwn=computed(()=>!!session.selected&&session.selected.membership.current_status==='ACTIVE'&&session.selected.membership.roles.includes('OWNER')&&!['SUSPENDED','CLOSED'].includes(session.selected.party.current_status))
const rows=ref<Invoice[]>([]),invoice=ref<Invoice|null>(null),eligibility=ref<InvoiceEligibility|null>(null),history=ref<InvoiceEvent[]>([]),documents=ref<InvoiceDocument[]>([]),cursor=ref<string|null>(null),historyCursor=ref<number|null>(null),documentsCursor=ref<string|null>(null),status=ref(''),loading=ref(false),historyLoading=ref(false),documentsLoading=ref(false),historyError=ref<ApiError|null>(null),documentsError=ref<ApiError|null>(null),historyLoaded=ref(false),documentsLoaded=ref(false)
const listSeen=new Set<string>(),historySeen=new Set<number>(),documentSeen=new Set<string>()
const actions=computed(()=>invoice.value&&(operator.value||canOwn.value)?invoiceAvailableActions(invoice.value,role.value):[])
const base=computed(()=>invoiceBase(role.value)),routeBase=computed(()=>invoiceRoute(role.value)),recording=computed(()=>action.value==='RECORD_DOCUMENT'),canSubmit=computed(()=>!locked.value&&!loading.value&&confirmed.value&&(!conflicted.value||reconfirmed.value))
const headerValid=computed(()=>isInvoiceHeader(header.value)&&header.value.title===header.value.title.trim()&&(header.value.tax_id===null||header.value.tax_id===header.value.tax_id.trim()))
const recordValid=computed(()=>{const i=invoice.value,a=invoiceAmount(amount.value,!!i?.issued_document_id);return !!i&&a!==null&&a<=i.available_for_this_request_minor&&a<=i.occupied_minor&&(!!i.issued_document_id||a===i.occupied_minor&&JSON.stringify(header.value)===JSON.stringify(i.header))&&reference.value.trim()&&Number.isFinite(Date.parse(issuedAt.value))&&Date.parse(issuedAt.value)<=Date.now()&&(i.environment==='SANDBOX'?assets.value.length===0:assets.value.length===1&&assets.value[0]?.media_type==='application/pdf'&&canOwn.value)})
let initialized=false,generation=0,controller=new AbortController()
function initialize(){initialized=true;void load()}
function clearRecords(){rows.value=[];invoice.value=null;eligibility.value=null;history.value=[];documents.value=[];cursor.value=historyCursor.value=documentsCursor.value=null;listSeen.clear();historySeen.clear();documentSeen.clear();historyLoaded.value=documentsLoaded.value=false;historyError.value=documentsError.value=null}
function clearDraft(){text.value=amount.value=reference.value=issuedAt.value='';header.value={kind:'PERSON',title:'',tax_id:null};baseline.value=JSON.stringify(header.value);assets.value=[];action.value='';confirmed.value=false;conflicted.value=reconfirmed.value=false;uploadLocked.value=false}
function reset(){generation++;controller.abort();controller=new AbortController();loading.value=historyLoading.value=documentsLoading.value=false;clearRecords();clearDraft()}
function privateFailure(e:ApiError){if([401,403,404].includes(e.status)){error.value=e;header.value={kind:'PERSON',title:'',tax_id:null};baseline.value=JSON.stringify(header.value);assets.value=[];generation++;controller.abort();controller=new AbortController();clearRecords();loading.value=historyLoading.value=documentsLoading.value=false}}
async function read<T>(path:string,guard:(v:unknown)=>v is T,onError:(e:ApiError)=>void=e=>{error.value=e}):Promise<T|null>{if(!ui.ready.value)return null;const g=generation;try{const r=await serviceRequest(ui.identity(),path,guard,{signal:controller.signal});return g===generation?r:null}catch(e){if(g===generation){const problem=asApiError(e);privateFailure(problem);onError(problem)}return null}}
async function load(more=false){
 if(loading.value||locked.value||!ui.ready.value||!operator.value&&!session.selectedId)return
 const g=generation;loading.value=true;error.value=null
 if(creating.value){eligibility.value=null;if(validSupplyId(orderId.value))eligibility.value=await read('/invoices/orders/'+orderId.value+'/eligibility',(v):v is InvoiceEligibility=>isInvoiceEligibility(v)&&v.order_id===orderId.value);else ui.fail('请从原订单进入开票申请。');if(g===generation)loading.value=false;return}
 if(id.value){invoice.value=null;history.value=[];documents.value=[];historyCursor.value=documentsCursor.value=null;historySeen.clear();documentSeen.clear();historyLoaded.value=documentsLoaded.value=false;historyError.value=documentsError.value=null;const target=id.value,r=await read(base.value+'/'+target,(v):v is Invoice=>isInvoice(v)&&v.id===target&&(operator.value||v.buyer_party_id===session.selectedId));if(g!==generation)return;invoice.value=r;if(r){if(!dirty.value){header.value=JSON.parse(JSON.stringify(r.header));baseline.value=JSON.stringify(header.value)}if(!actions.value.includes(action.value as InvoiceAction))action.value='';await loadHistory();if(invoice.value)await loadDocuments()}if(g===generation)loading.value=false;return}
 const old=more?cursor.value:null;if(!more){rows.value=[];cursor.value=null;listSeen.clear()}
 const r=await read(base.value+query({status:status.value,cursor:old,limit:20}),invoicePage((v):v is Invoice=>isInvoice(v)&&(operator.value||v.buyer_party_id===session.selectedId)))
 if(g!==generation)return
 if(r){if(r.next_cursor!==null&&(old!==null&&r.next_cursor<=old||listSeen.has(r.next_cursor)))ui.fail('开票列表游标未前进，请刷新列表。');else{if(old)listSeen.add(old);rows.value=more?[...new Map([...rows.value,...r.items].map(x=>[x.id,x])).values()]:r.items;cursor.value=r.next_cursor}}
 loading.value=false
}
async function loadHistory(more=false){if(!invoice.value||historyLoading.value||more&&historyCursor.value===null)return;const target=invoice.value.id,g=generation,old=more?historyCursor.value:null;historyLoading.value=true;historyError.value=null;const r=await read(base.value+'/'+target+'/history'+query({cursor:old,limit:20}),invoicePage<InvoiceEvent,number>(isInvoiceEvent,true),e=>{historyError.value=e});if(g!==generation)return;if(r&&invoice.value?.id===target){if(r.next_cursor!==null&&(old!==null&&r.next_cursor<=old||historySeen.has(r.next_cursor)))historyError.value=new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'处理记录游标未前进，请重新读取。'});else{if(old!==null)historySeen.add(old);history.value=more?[...new Map([...history.value,...r.items].map(x=>[x.object_version,x])).values()]:r.items;historyCursor.value=r.next_cursor;historyLoaded.value=true}}historyLoading.value=false}
async function loadDocuments(more=false){if(!invoice.value||documentsLoading.value||more&&documentsCursor.value===null)return;const target=invoice.value,g=generation,old=more?documentsCursor.value:null;documentsLoading.value=true;documentsError.value=null;const r=await read(base.value+'/'+target.id+'/documents'+query({cursor:old,limit:20}),invoicePage((v):v is InvoiceDocument=>isInvoiceDocument(v)&&v.content.invoice_id===target.id&&v.content.order_id===target.order_id&&v.content.environment===target.environment&&v.content.issuer.merchant_party_id===target.issuer_party_id&&(operator.value||['ISSUED','SUPERSEDED'].includes(v.current_status))),e=>{documentsError.value=e});if(g!==generation)return;if(r&&invoice.value?.id===target.id){if(r.next_cursor!==null&&(old!==null&&r.next_cursor<=old||documentSeen.has(r.next_cursor)))documentsError.value=new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'票据游标未前进，请重新读取。'});else{if(old)documentSeen.add(old);documents.value=more?[...new Map([...documents.value,...r.items].map(x=>[x.id,x])).values()]:r.items;documentsCursor.value=r.next_cursor;documentsLoaded.value=true}}documentsLoading.value=false}
async function submit(){const e=eligibility.value,a=invoiceAmount(amount.value);if(!canSubmit.value||!canOwn.value||!e||a===null||a>e.available_minor||!e.environment||!headerValid.value||!text.value.trim())return;await ui.write('/invoices/requests',{order_id:e.order_id,amount_minor:a,header:header.value,text:text.value.trim(),asset_ids:assets.value.map(x=>x.id)},(v):v is Invoice=>isInvoice(v)&&v.order_id===e.order_id&&v.buyer_party_id===session.selectedId,async r=>{clearDraft();await router.push('/invoices/requests/'+r.id)});await afterFailure()}
async function act(){const i=invoice.value,a=action.value;if(!i||!a||!actions.value.includes(a)||!canSubmit.value||!text.value.trim()||a==='SUPPLEMENT'&&!headerValid.value||a==='RECORD_DOCUMENT'&&(!headerValid.value||!recordValid.value))return;const body={action:a,text:text.value.trim(),...(a==='SUPPLEMENT'?{header:header.value,asset_ids:assets.value.map(x=>x.id)}:{}),...(a==='RECORD_DOCUMENT'?{document:{amount_minor:invoiceAmount(amount.value,!!i.issued_document_id),reference:reference.value.trim(),issued_at:new Date(issuedAt.value).toISOString(),asset_id:i.environment==='SANDBOX'?null:assets.value[0]?.id,header:header.value}}:{})};await ui.write(base.value+'/'+i.id+'/actions',body,(v):v is Invoice=>isInvoice(v)&&v.id===i.id&&v.object_version>i.object_version,async()=>{clearDraft();await load()},{ifMatch:i.object_version});await afterFailure()}
async function afterFailure(){const e=error.value;if(!e)return;if([401,403,404].includes(e.status)){privateFailure(e);error.value=e;return}if(e.status===412){conflicted.value=true;reconfirmed.value=confirmed.value=false;action.value='';await load();notice.value='记录已变化，已重读最新状态。请核对保留的输入并重新选择操作、确认提交。';error.value=e}else if(['INVOICE_AMOUNT_UNAVAILABLE','INVOICE_STATE_CONFLICT','INVOICE_ISSUER_CHANGED'].includes(e.code)){confirmed.value=false;await load();error.value=e}}
async function retry(){await ui.retry();await afterFailure()}
async function download(asset:string,doc?:InvoiceDocument){if(!invoice.value||locked.value)return;const g=generation,target=invoice.value.id;error.value=null;try{const blob=await requestBytes(base.value+'/'+target+(doc?'/documents/'+doc.id:'/assets/'+asset)+'/content',{token:session.token,actingParty:operator.value?null:session.selectedId,signal:controller.signal});if(g!==generation||invoice.value?.id!==target)return;if(doc?.content.asset_proof){const p=doc.content.asset_proof,hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()))].map(n=>n.toString(16).padStart(2,'0')).join('');if(g!==generation)return;if(blob.size!==p.byte_size||hash!==p.content_sha256)throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'票据文件校验不一致，未下载。'})}if(blob.size<1||blob.size>8388608)throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'文件大小不符合材料限制，未下载。'});if(doc?.content.simulated){const text=await blob.text();if(g!==generation)return;if(text!=='模拟凭证，非真实发票\n'+JSON.stringify(doc.content,null,2)+'\n')throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'模拟凭证与当前票据内容不一致，未下载。'})}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=doc?(doc.content.simulated?'模拟凭证-非真实发票-':'票据-')+doc.id+(doc.content.simulated?'.txt':'.pdf'):'开票申请材料-'+asset;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(g===generation){const problem=asApiError(e);if([403,404,409].includes(problem.status)){documents.value=[];history.value=[];documentsLoaded.value=historyLoaded.value=false}privateFailure(problem);error.value=problem}}}
onUnmounted(()=>{generation++;controller.abort()})
watch(ui.revision,()=>{reset();if(initialized&&ui.ready.value)void load()},{flush:'sync'})
watch(status,()=>{generation++;controller.abort();controller=new AbortController();loading.value=false;void load()})
watch(action,()=>{confirmed.value=false;if(action.value==='RECORD_DOCUMENT'&&invoice.value&&!amount.value){amount.value=(invoice.value.occupied_minor/100).toFixed(2);header.value=JSON.parse(JSON.stringify(invoice.value.header));baseline.value=JSON.stringify(header.value)}})
watch([text,amount,header,reference,issuedAt,assets],()=>{confirmed.value=false},{deep:true,flush:'sync'})
reset()
</script>
<template><ServiceWorkspace :title="creating?'从原订单申请开票':role==='handle'?'开票受理与录入':role==='verify'?'票据独立核准':'我的开票'" intro="依据原订单已核验收款办理，申请、开具与更正分别留存记录。" :account-only="operator" :locked="locked" :dirty="dirty" :error="error" :notice="notice" @ready="initialize">
 <div class="service-tabs"><RouterLink to="/invoices/requests">我的开票</RouterLink><RouterLink to="/invoices/operations/handle">受理与录入</RouterLink><RouterLink to="/invoices/operations/verify">独立核准</RouterLink></div>
 <p v-if="operator" class="service-muted">受理录入与票据核准分别授权；不得处理本人或关联身份的申请，也不得核准自己录入的票据。</p>
 <section v-if="pending" class="service-pending"><p>原请求结果尚未确认，已保留原内容、版本和请求。请先恢复，勿另建申请。</p><button class="outline" :disabled="busy" @click="retry">恢复原开票请求</button></section>
 <p v-if="loading" role="status">正在核对开票记录…</p>
 <section v-if="creating" class="supply-card"><RouterLink :to="'/trade/orders/'+orderId" class="button-link outline">返回原订单</RouterLink><h2>本单可申请额度</h2><button class="outline" :disabled="locked||loading" @click="load()">重新核对额度</button><template v-if="eligibility"><p>{{eligibility.environment==='SANDBOX'?'测试环境，仅模拟凭证':eligibility.environment==='PRODUCTION'?'正式环境':'本单没有已核验现金收款'}}</p><dl class="supply-facts"><div v-for="(label,key) in {received_minor:'已核验收款',refunded_minor:'已核验退款',pending_refund_minor:'退款处理中占用',occupied_minor:'已有开票申请占用',available_minor:'当前可申请'}" :key="key"><dt>{{label}}</dt><dd>{{invoiceMoney(eligibility[key])}}</dd></div></dl><p v-if="!eligibility.environment||eligibility.available_minor===0" class="supply-warning">当前没有可申请额度。仅权益支付不产生现金开票额度。</p><form v-if="eligibility.environment&&eligibility.available_minor>0" @submit.prevent="submit"><fieldset :disabled="locked||loading||!canOwn"><InvoiceHeaderFields v-model="header"/><label class="service-field">申请金额（元）<input v-model="amount" inputmode="decimal" required></label><label class="service-field">申请说明<textarea v-model="text" maxlength="2000" rows="4" required/></label><PrivateAssetPicker v-model="assets" :max="8" :disabled="busy||!!pending" @lock="uploadLocked=$event"/><label class="trade-check"><input v-model="confirmed" type="checkbox">我已核对原订单、金额和抬头，确认提交申请。</label><button class="primary" data-testid="invoice-submit" :disabled="!canSubmit||!headerValid||invoiceAmount(amount)===null||(invoiceAmount(amount)??Infinity)>eligibility.available_minor||!text.trim()">确认申请开票</button></fieldset></form></template></section>
 <section v-else-if="!id" class="supply-card"><div class="service-form"><label>申请状态<select v-model="status" :disabled="locked||loading"><option value="">全部状态</option><option v-for="(label,key) in invoiceStatuses" :key="key" :value="key">{{label}}</option></select></label><button class="outline" :disabled="locked||loading" @click="load()">刷新开票列表</button><RouterLink v-if="!operator" to="/trade/orders" class="button-link outline">到原订单核对开票额度</RouterLink></div><article v-for="item in rows" :key="item.id" class="service-result"><p class="service-muted">{{item.environment==='SANDBOX'?'测试环境':'正式环境'}} · {{invoiceStatuses[item.current_status]}}</p><h2>{{item.header.title}} · 申请 {{invoiceMoney(item.requested_minor)}}</h2><p>当前占用 {{invoiceMoney(item.occupied_minor)}}</p><p class="service-id">原订单 {{item.order_id}}</p><RouterLink :to="routeBase+'/'+item.id" class="button-link outline">查看开票办理</RouterLink></article><p v-if="!rows.length&&!cursor&&!error&&!loading">暂无当前权限可读取的开票申请。</p><button v-if="cursor" class="outline" :disabled="locked||loading" @click="load(true)">继续读取开票申请</button></section>
 <template v-else-if="invoice"><section class="supply-card"><p class="service-muted">{{invoice.environment==='SANDBOX'?'测试环境 · 模拟凭证，非真实发票':'正式环境'}}</p><h2>{{invoice.header.title}}</h2><p class="service-status">{{invoiceStatuses[invoice.current_status]}}</p><p v-if="invoice.header.tax_id">纳税人识别号：{{invoice.header.tax_id}}</p><dl class="supply-facts"><div><dt>原申请金额</dt><dd>{{invoiceMoney(invoice.requested_minor)}}</dd></div><div><dt>本申请占用额度</dt><dd>{{invoiceMoney(invoice.occupied_minor)}}</dd></div><div><dt>本申请当前额度上限</dt><dd>{{invoiceMoney(invoice.available_for_this_request_minor)}}</dd></div></dl><p class="service-id">申请 {{invoice.id}} · 版本 {{invoice.object_version}}</p><p v-if="invoice.requires_correction" class="supply-warning">退款或额度变化后，本票据需要人工核对更正。</p><p v-if="invoice.current_status==='CORRECTION_REQUESTED'||invoice.requires_correction" class="service-muted">更正票据保留历史文件。更正金额为零也不表示发生退款；退款结果须回原订单核对。</p><div class="service-actions"><RouterLink v-if="!operator" :to="'/trade/orders/'+invoice.order_id" class="button-link outline">查看原订单与退款</RouterLink><button class="outline" :disabled="locked||loading" @click="load()">刷新申请状态</button></div></section>
 <section class="supply-card"><h2>{{operator?'票据录入与历史文件':'已开具的票据'}}</h2><ApiErrorAlert :error="documentsError"/><button v-if="documentsError" class="outline" :disabled="documentsLoading||locked" @click="loadDocuments(documentsCursor!==null)">重读票据列表</button><article v-for="doc in documents" :key="doc.id" class="service-result"><h3>{{doc.content.reference}} · {{invoiceMoney(doc.content.amount_minor)}}</h3><p>{{ {PENDING:'本次录入，尚未核准',REJECTED:'本次票据已退回',ISSUED:'当前可领取票据',SUPERSEDED:'已被更正的历史票据'}[doc.current_status] }}</p><p v-if="doc.current_status==='ISSUED'&&doc.content.amount_minor===0&&doc.content.replaces_document_id" class="supply-notice" data-testid="invoice-zero-correction">已作金额归零更正；原票据保留为历史记录。本次更正不代表退款，实际退款结果请回原订单核对。</p><p>{{doc.content.label}}</p><p>{{doc.content.header.title}}<span v-if="doc.content.header.tax_id"> · {{doc.content.header.tax_id}}</span></p><p class="service-muted">开具时间 {{new Date(doc.content.issued_at).toLocaleString()}} · 开具方 {{doc.content.issuer.name}}</p><button class="outline" :disabled="locked" @click="download('',doc)">{{operator?'读取受控票据文件':doc.current_status==='SUPERSEDED'?'领取历史票据':'领取当前票据'}}</button></article><p v-if="!documents.length&&documentsLoaded&&!documentsError">{{operator?'尚无已登记票据。':'尚无可领取票据。申请批准或待独立核准均不代表已经开具。'}}</p><button v-if="documentsCursor" class="outline" :disabled="locked||documentsLoading" @click="loadDocuments(true)">继续读取票据</button></section>
 <section class="supply-card"><h2>申请与处理历史</h2><ApiErrorAlert :error="historyError"/><button v-if="historyError" class="outline" :disabled="locked||historyLoading" @click="loadHistory(historyCursor!==null)">重读处理记录</button><ol class="service-history"><li v-for="event in history" :key="event.object_version"><p><strong>{{event.actor_kind==='APPLICANT'?'申请人':'工作人员'}} · {{event.action==='SUBMIT'?'提交申请':invoiceActions[event.action]}}</strong> · {{new Date(event.created_at).toLocaleString()}}</p><p class="service-text">{{event.text}}</p><p class="service-muted">{{invoiceStatuses[event.status]}} · {{invoiceMoney(event.amount_minor)}}</p><div class="service-actions"><button v-for="asset in (['SUBMIT','SUPPLEMENT'].includes(event.action)?event.asset_ids:[])" :key="asset" class="outline" :disabled="locked" @click="download(asset)">读取本次申请材料 {{asset.slice(0,8)}}</button></div></li></ol><button v-if="historyCursor!==null" class="outline" :disabled="locked||historyLoading" @click="loadHistory(true)">继续读取后续处理记录</button></section>
 <p v-if="operator&&invoice.allowed_actions===undefined" class="supply-warning">当前仅可查看记录，办理权限待平台核对，请联系平台管理员。</p>
 <form v-if="actions.length" class="supply-card" @submit.prevent="act"><fieldset :disabled="locked||loading"><h2>本次办理</h2><p v-if="conflicted" class="supply-warning"><label class="trade-check"><input v-model="reconfirmed" type="checkbox">我已核对重读后的最新状态，将重新作出本次决定。</label></p><label class="service-field">办理事项<select v-model="action" required data-testid="invoice-action"><option value="">请选择</option><option v-for="a in actions" :key="a" :value="a">{{invoiceActions[a]}}</option></select></label><InvoiceHeaderFields v-if="action==='SUPPLEMENT'||recording" v-model="header" :disabled="recording&&!invoice.issued_document_id"/><template v-if="recording"><label class="service-field">票据金额（元）<input v-model="amount" inputmode="decimal" :readonly="!invoice.issued_document_id" required></label><p class="service-muted">首次票据抬头和金额与申请一致；更正不得增加原占用额度。</p><label class="service-field">票据编号／外部依据<input v-model="reference" maxlength="200" required></label><label class="service-field">实际开具时间<input v-model="issuedAt" type="datetime-local" required></label><p v-if="invoice.environment==='SANDBOX'" class="supply-warning">服务器生成“模拟凭证，非真实发票”，不上传正式票据。</p><template v-else><p class="service-muted">请选工作人员本人获准管理的上传身份，再上传本次 PDF；不使用申请人的主体上传。</p><PrivateAssetPicker v-model="assets" pdf-only :max="1" :disabled="busy||!!pending||!canOwn" @lock="uploadLocked=$event"/></template></template><PrivateAssetPicker v-if="action==='SUPPLEMENT'" v-model="assets" :max="8" :disabled="busy||!!pending" @lock="uploadLocked=$event"/><label class="service-field">本次说明<textarea v-model="text" rows="4" maxlength="2000" required/></label><label class="trade-check"><input v-model="confirmed" type="checkbox">我已核对本次事项及当前记录，确认提交。</label><button class="primary" data-testid="invoice-action-submit" :disabled="!canSubmit||!action||!text.trim()||recording&&!recordValid||(action==='SUPPLEMENT'||recording)&&!headerValid">确认本次办理</button></fieldset></form>
 </template><section v-else-if="id&&!loading" class="supply-card"><p>未读取到可办理的开票申请，请重新核对记录与权限。</p><button class="outline" :disabled="locked" @click="load()">重新读取申请</button></section>
 </ServiceWorkspace></template>
